     9→ *
    10→ * 寄存器来源: bk_idk/include/soc/bk7258/reg_base.h + uart_struct.h
    11→ *   SOC_UART0_REG_BASE = 0x44820000
    12→ *   fifo_port 寄存器偏移 0x07 * 4 = 0x1C
    13→ *   写 bit[0:7] = tx_fifo_data_in 即发一个字节
    14→ */
    15→
    16→#include <zephyr/kernel.h>
    17→
    18→/* 使用 UART1: TX=P00, RX=P01（UART0 被 BKFIL 下载占用） */
    19→#define BK_UART1_BASE       0x45830000U
    20→#define BK_UART1_FIFO_PORT  (BK_UART1_BASE + 0x07U * 4U)
    21→#define BK_UART1_FIFO_STATUS (BK_UART1_BASE + 0x06U * 4U)
    22→#define BK_UART1_TX_FIFO_EMPTY_BIT  (1U << 17)
    23→#define BK_UART1_TX_FULL_BIT        (1U << 16)
    24→
    25→#define TX_FIFO_DATA_IN(bit8_val)  ((uint32_t)(bit8_val) & 0xFF)
    26→
    27→static inline void bk_uart0_putc(char c)
    28→{
    29→	volatile uint32_t *fifo_port = (volatile uint32_t *)BK_UART1_FIFO_PORT;
    30→	volatile uint32_t *fifo_sts  = (volatile uint32_t *)BK_UART1_FIFO_STATUS;
    31→
    32→	/* 等 TX FIFO 非满（最多等一阵） */
    33→	uint32_t timeout = 0xFFFFF;
    34→	while (((*fifo_sts) & BK_UART1_TX_FULL_BIT) && timeout--) {
    35→	}
    36→
    37→	/* 写字节到 tx_fifo_data_in (bit[0:7]) */
    38→	*fifo_port = TX_FIFO_DATA_IN((uint32_t)c);
    39→}
