    41→static void bk_uart0_puts(const char *s)
    42→{
    43→	while (*s) {
    44→		if (*s == '\n') {
    45→			bk_uart0_putc('\r');
    46→		}
    47→		bk_uart0_putc(*s++);
    48→	}
    49→}
